-- PT120-S1-Q3. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT120-S1-Q3$batch10$ AND q.stimulus=$batch10$When a lawmaker spoke out against a research grant awarded to a professor in a university’s psychology department as a foolish expenditure of public money, other professors in that department drafted a letter protesting the lawmaker’s interference in a field in which he was not trained. The chair of the psychology department, while privately endorsing the project, refused to sign the protest letter on the ground that she had previously written a letter applauding the same legislator when he publicized a senseless expenditure by the country’s military.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if established, provides the strongest justification for the department chair's refusal, on the ground she gives, to sign the protest letter?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT120-S1-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT120-S1-Q3$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S1-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT120-S1-Q3$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$The chair refuses to sign the letter protesting the lawmaker's interference.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The chair had earlier written a letter praising the same lawmaker for publicizing a senseless military expenditure.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The chair's ground is consistency: having praised the lawmaker for acting as a watchdog in one case, the chair can't protest the same watchdog role now. The principle has to say that, even when the new case touches the chair's own field.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Someone who praised a lawmaker for being a watchdog in one case shouldn't criticize the lawmaker for doing the same in a case involving that person's own professional interests.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT120-S1-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This asks for careful thought before criticizing. It doesn't tell the chair not to criticize, and the chair's reason is the earlier praise, not a lack of care.$batch10$), ($batch10$B$batch10$, $batch10$The chair's duty over department funds isn't the reason given. The chair privately backs the project anyway.$batch10$), ($batch10$C$batch10$, $batch10$The chair praised the lawmaker's watchdog role over the military spending. Now the lawmaker plays the same role in the chair's own department. This principle says the chair shouldn't criticize the lawmaker in that situation.$batch10$), ($batch10$D$batch10$, $batch10$This bars academics from judging government officials because of taxes and funding. The chair's stated ground is the earlier letter, not tax status.$batch10$), ($batch10$E$batch10$, $batch10$This compares universities and the military on spending wisely. It doesn't explain why the chair, having praised the lawmaker, shouldn't sign.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT120-S1-Q3$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
